/**  An online music database the tag search asks. */
export type TagSource = 
/**  AcoustID, which recognises the recording by its sound and names it as MusicBrainz does. */
"acoustId" | "musicBrainz" | 
/**  The iTunes store of Russia, whose names keep their own script. */
"itunesRu" | 
/**  The iTunes store of the United States, whose names are mostly in Latin letters. */
"itunesUs" | "deezer" | 
/**  Bandcamp, where artists and small labels sell their own music. */
"bandcamp" | 
/**  YouTube Music, whose songs are releases and whose videos are uploads. */
"youtubeMusic";

/**  The command line programs downloads need, by name. */
export type Tool = "ytDlp" | "ffmpeg" | "deno";

/**  A tool being fetched; `total_bytes` is null when the server does not say. */
export type ToolInstall = {
  tool: Tool,
  doneBytes: number,
  totalBytes: number | null,
};

/**  Installed version of each tool, missing ones as null. */
export type ToolVersions = {
  ytDlp: string | null,
  ffmpeg: string | null,
  deno: string | null,
};

/**  The download tools were installed, updated or are being fetched. */
export type ToolsChanged = ToolsView;

export type ToolsView = {
  versions: ToolVersions,
  installing: ToolInstall | null,
  updating: boolean,
  /**  Unix seconds of the last update check. */
  checkedAt: number | null,
};

export type Track = {
  id: TrackId,
  path: string,
  title: string,
  /**  The credited artists in order, the main one first; empty when the file names none. */
  artists: ArtistName[],
  /**  The album the song is on; a song whose file names none is on no album. */
  albumId: AlbumId | null,
  album: string | null,
  /**  Its album's cover, or the cover of its own file when it is on no album. */
  cover: string | null,
  trackNo: number | null,
  discNo: number | null,
  durationMs: number,
  presence: Presence,
};

/**  The tags the edit dialog sends for one song; blank text, empty lists and missing numbers clear those tags. */
export type TrackEdit = {
  title: string,
  /**  The credited artists in order, the main one first. */
  artists: string[],
  /**
  *  Whose the album is when that is not the main artist alone, as on compilations and joint albums; it goes to
  *  every song of the album.
  */
  albumArtists: string[],
  album: string | null,
  year: number | null,
  releaseType: ReleaseType | null,
  trackNo: number | null,
  discNo: number | null,
  genres: string[],
  composers: string[],
  lyricists: string[],
  comment: string | null,
  /**  Blank clears them, and the song's lyrics are then looked up online like those of any song without. */
  lyrics: string | null,
  cover: CoverChange,
};

/**  One audio file of the library. */
export type TrackId = number;

/**  Tags of one song file as the edit dialog shows them, with facts about the file next to them. */
export type TrackTags = {
  path: string,
  title: string,
  /**  The credited artists in order; empty when the file names none. */
  artists: string[],
  /**  Empty unless the file names album artists of its own, as compilations and joint albums do. */
  albumArtists: string[],
  album: string | null,
  year: number | null,
  releaseType: ReleaseType | null,
  trackNo: number | null,
  discNo: number | null,
  genres: string[],
  composers: string[],
  lyricists: string[],
  comment: string | null,
  /**  The lyrics the file's own tag holds, plain or timed as LRC; lyrics kept in a separate `.lrc` file are not among them. */
  lyrics: string | null,
  /**  The file type by its extension, such as `MP3`. */
  format: string,
  bitrateKbps: number | null,
  durationMs: number,
};

/**
*  How the window behaves: whether closing it hides it to the tray, and whether a launch by Windows at sign-in stays
*  in the tray without showing it.
*/
export type WindowSettings = {
  closeToTray: boolean,
  startHidden: boolean,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
  try {
    return { status: "ok", data: await result };
  } catch (e) {
    if (e instanceof Error) throw e;
    return { status: "error", error: e as any };
  }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
  const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
  const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

  const base = {
    listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
    once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
    emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
    emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
  };

  const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
    listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
    once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
    emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
    emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
  });

  return Object.assign(fn, base);
}

